-- ----------------------------------------------------------------------------
-- Unit 1 self-ratings pointed at target slugs that do not exist (u1.d1 … u1.d22,
-- l5-first-law), so MC-2 calibration could never join them. Re-point each marzano
-- at the day's real target (applied 2026-09-03).
-- ----------------------------------------------------------------------------
with m(bad, good) as (values
 ('u1.d1','u1.anchor-know-unknow'),('u1.d3','u1.capture-pt-graph'),('u1.d4','u1.read-vt-graph-components'),('u1.d5','u1.predict-position-uncertainty'),('u1.d6','u1.vectors-tip-to-tail'),('u1.d7','u1.acceleration-rate-of-change'),('u1.d8','u1.pick-equation-of-motion'),('l5-first-law','u1.newtons-first-law-inertia'),('u1.d10','u1.identify-forces'),('u1.d11','u1.lab-accel-vs-mass'),('u1.d12','u1.lab-accel-vs-force'),('u1.d13','u1.fma-solve-net-force'),('u1.d14','u1.third-law-pairs'),('u1.d15','u1.draw-fbd'),('u1.d16','u1.net-force-from-fbd'),('u1.d17','u1.friction-static-kinetic'),('u1.d18','u1.equilibrium-find-unknown'),('u1.d19-fbd','u1.draw-fbd'),('u1.d19-vectors','u1.vectors-tip-to-tail'),('u1.d19-fma','u1.fma-solve-net-force'),('u1.d19','u1.workshop-self-diagnose'),('u1.d20','u1.d20-locate-the-arc'),('u1.d21','u1.d08-kinematics-transfer'),('u1.d22','u1.d08-kinematics-transfer'))
update public.lessons l set content_blocks = jsonb_set(l.content_blocks, '{blocks}', (
  select jsonb_agg(case when b->>'type'='marzano' and exists (select 1 from m where m.bad = b->>'targetId') then b || jsonb_build_object('targetId', (select good from m where m.bad = b->>'targetId')) else b end order by o)
  from jsonb_array_elements(l.content_blocks->'blocks') with ordinality as x(b,o)))
where l.unit_id='unit-1' and exists (select 1 from jsonb_array_elements(l.content_blocks->'blocks') b join m on m.bad = b->>'targetId' where b->>'type'='marzano');

